using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>Exercises HttpPaymentGateway over real HTTP against a local fake provider.</summary>
public sealed class HttpPaymentGatewayTests : IAsyncDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Task loop;
    private int status = 200;
    private string responseBody = "{}";

    public string? Method { get; private set; }
    public string? Path { get; private set; }
    public string? ContentType { get; private set; }
    public string? RequestBody { get; private set; }

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
        loop = Task.Run(Serve);
    }

    private static int FreePort()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); }
            catch { return; }

            Method = ctx.Request.HttpMethod;
            Path = ctx.Request.Url!.AbsolutePath;
            ContentType = ctx.Request.ContentType;
            using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8))
                RequestBody = await reader.ReadToEndAsync();

            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            var bytes = Encoding.UTF8.GetBytes(responseBody);
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private void Provider(int statusCode, string body)
    {
        status = statusCode;
        responseBody = body;
    }

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-1", decimal amount = 12.50m, string currency = "eur") =>
        new HttpPaymentGateway(client).AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        Provider(200, """{"status":"approved"}""");

        await Authorize("ORD-42", 12.50m, "eur");

        Assert.Equal("POST", Method);
        Assert.Equal("/v1/authorizations", Path);
        Assert.StartsWith("application/json", ContentType);
        using var doc = JsonDocument.Parse(RequestBody!);
        var root = doc.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-42", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal(JsonValueKind.Number, root.GetProperty("amount").ValueKind);
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_back_as_approved()
    {
        Provider(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_back_as_declined()
    {
        Provider(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Provider(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_not_an_error()
    {
        Provider(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_still_a_decline()
    {
        Provider(402, "");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"result":"approved"}""")]
    [InlineData("null")]
    public async Task Anything_other_than_an_exact_approved_status_is_never_treated_as_approval(string body)
    {
        Provider(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_rather_than_decisions(int code)
    {
        Provider(code, """{"status":"approved"}""");
        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_as_a_failure()
    {
        Provider(200, "<html>oops</html>");
        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    public async ValueTask DisposeAsync()
    {
        listener.Stop();
        listener.Close();
        await loop;
        client.Dispose();
    }
}
